 if($method==='GET'&&$path==='/commands/pending'){bridge_auth();$siteId=selected_site($pdo);$q=$pdo->prepare("SELECT c.id command_id,h.node_id,c.base_id,c.sequence_number,c.command_type,c.status,c.route_type,c.route_via_node_id,c.created_at,c.fetched_at,c.sent_at FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE c.status='QUEUED' AND c.site_id=? ORDER BY c.id LIMIT 100");$q->execute([$siteId]);$commands=$q->fetchAll();if($commands){$ids=array_map(fn($c)=>(int)$c['command_id'],$commands);$marks=implode(',',array_fill(0,count($ids),'?'));$u=$pdo->prepare("UPDATE downlink_commands SET fetched_at=COALESCE(fetched_at,CURRENT_TIMESTAMP(3)) WHERE status='QUEUED' AND id IN ($marks)");$u->execute($ids);$q=$pdo->prepare("SELECT c.id command_id,h.node_id,c.base_id,c.sequence_number,c.command_type,c.status,c.route_type,c.route_via_node_id,c.created_at,c.fetched_at,c.sent_at FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE c.id IN ($marks) ORDER BY c.id");$q->execute($ids);$commands=$q->fetchAll();}foreach($commands as &$c){$c['type']=downlink_type($c['command_type']);unset($c['command_type']);$c['sequence_number']=$c['sequence_number']===null?null:(int)$c['sequence_number'];$c=add_command_elapsed_times($c);}unset($c);respond(['commands'=>$commands]);}
