 if($method==='POST'&&preg_match('#^/commands/([0-9]+)/status$#',$path,$m)){bridge_auth();$v=body();$status=$v['status']??'';if(!in_array($status,['SENT_TO_BASE','DELIVERED','RECEIVED','FAILED','TIMED_OUT'],true))throw new InvalidArgumentException('invalid command status');$col=match($status){'SENT_TO_BASE'=>'sent_at','DELIVERED'=>'delivered_at','RECEIVED'=>'received_at',default=>null};$sql='UPDATE downlink_commands SET status=?,failure_reason=?'.($col?",$col=CURRENT_TIMESTAMP(3)":'').' WHERE id=?';$q=$pdo->prepare($sql);$q->execute([$status,isset($v['failure_reason'])?substr((string)$v['failure_reason'],0,500):null,(int)$m[1]]);if(!$q->rowCount())respond(['error'=>'command not found or unchanged'],404);$q=$pdo->prepare('SELECT id command_id,route_type,route_via_node_id,created_at,fetched_at,sent_at FROM downlink_commands WHERE id=?');$q->execute([(int)$m[1]]);$timing=add_command_elapsed_times($q->fetch()?:[]);respond(['ok'=>true,'status'=>$status,'command'=>$timing]);}
